import mongoose, { Schema, models } from 'mongoose';

const ResultSchema = new Schema(
  {
    userId: {
      type: String,
      required: true,
    },

    title: {
      type: String,
      required: true,
    },

    // Content generated by AI
    reviewer: {
      type: String,
    },

    // quizzes stored as an array
    quiz: [
      {
        question: String,
        answer: String,
        difficulty: String,
      },
    ],

    // flashcards
    flashcards: [
      {
        front: String,
        back: String,
      },
    ],

    // Identifies the type of saved result
    type: {
      type: String,
      enum: ['reviewer', 'quiz', 'flashcards'],
      required: true,
    },
  },
  {
    timestamps: true,
  }
);

export default models.Result || mongoose.model('Result', ResultSchema);
